/* From Uiverse.io by satyamchaudharydev - Tags: loader */
.__UIV_SCOPE__ .spinner {
 --gap: 5px;
 --clr: #d62d20;
 --height: 23px;
 width: 100px;
 height: 100px;
 display: flex;
 align-items: center;
 justify-content: center;
 gap: var(--gap);
}

.__UIV_SCOPE__ .spinner span {
 background: var(--clr);
 width: 6px;
 height: var(--height);
 animation: grow 1s ease-in-out infinite;
}

.__UIV_SCOPE__ .spinner span:nth-child(2) {
 animation: grow 1s ease-in-out 0.15s infinite;
}

.__UIV_SCOPE__ .spinner span:nth-child(3) {
 animation: grow 1s ease-in-out 0.3s infinite;
}

.__UIV_SCOPE__ .spinner span:nth-child(4) {
 animation: grow 1s ease-in-out 0.475s infinite;
}

@keyframes grow {
 0%,100% {
  transform: scaleY(1);
 }

 50% {
  transform: scaleY(1.8);
 }
}
